#include "hip_reference_network.h"
#include "production_options.generated.h"
#include <cstdio>
#include <chrono>
#include <fstream>
using namespace hip_reference;
static std::vector<char> read(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("input missing");std::vector<char>b(size_t(f.tellg()));f.seekg(0);if(!f.read(b.data(),b.size()))throw std::runtime_error("input short");return b;}
static void flags(const char*p){std::ifstream f(p);if(!f)throw std::runtime_error("flags missing");std::string s;while(std::getline(f,s)){if(s.empty()||s[0]=='#')continue;auto q=s.find('=');if(q==s.npos)continue;auto k=s.substr(0,q),v=s.substr(q+1);if(!v.empty()&&v.back()=='\r')v.pop_back();if(k.rfind("DLSS5_",0)==0)_putenv_s(k.c_str(),v.c_str());}}
int main(int argc,char**argv){try{
 if(argc!=9&&argc!=10)throw std::runtime_error("bench ASSETS MODULES FLAGS PROCESSING_F32 OUTDIR WARM MEASURED PH");flags(argv[3]);const std::string scenario=argc==10?argv[9]:"default";const unsigned mode=scenario=="mp2"?2u:1u;if(scenario=="fast0")_putenv_s("DLSS5_FAST_NUMERIC","0");if(scenario.rfind("missing-",0)==0)_putenv_s("GAP_HIDE_EXPORT",scenario.c_str());
 const U h=std::stoul(argv[8]),w=h==960?1600:1920,valid=h==960?900:1080,tokens=h==960?400:640,warm=std::stoul(argv[6]),measured=std::stoul(argv[7]);if((h!=960&&h!=1088&&h!=1152)||warm||!measured||measured>3)throw std::runtime_error("bounded sample count");
 for(const char*k:{"DLSS5_MULTI_PASS_PREDICT","DLSS5_MULTI_PASS_SKIN_PROTECT","DLSS5_HIP_GRAPH","DLSS5_OVERLAP","DLSS5_VIT_ADAPTIVE","DLSS5_VIT_REUSE_HOTKEY","DLSS5_TEMPORAL_HISTORY_EXPERIMENT","DLSS5_TEMPORAL_MV_UNJITTERED"})_putenv_s(k,"0");_putenv_s("DLSS5_MULTI_PASS",mode==2?"2":"1");_putenv_s("DLSS5_STYLE","1");_putenv_s("DLSS5_SKIP_BLOCKS","");
 auto input=read(argv[4]);if(input.size()!=size_t(w)*h*16)throw std::runtime_error("input footprint");auto opt=production_options(argv[1],argv[2],w,h,false);opt.experimental_temporal=false;opt.skip_blocks.clear();if(!opt.wave_owned||!opt.c512_m32||!opt.pdl||opt.vit_stream!=3||!opt.swin_run)throw std::runtime_error("production profile missing");printf("SYNC_PROFILE wave_owned=%u c512_m32=%u pdl=%u vit_stream=%u swin_run=%u FAST=%s full71=%u\n",unsigned(opt.wave_owned),unsigned(opt.c512_m32),unsigned(opt.pdl),opt.vit_stream,unsigned(opt.swin_run),std::getenv("DLSS5_FAST_NUMERIC"),unsigned(opt.skip_blocks.empty()));Network net(opt);if(net.ModelMode()!=mode||net.EffectiveModelMode()!=mode||net.MultiPass()!=mode)throw std::runtime_error("Original 1x required");printf("KNIFE1_CASE name=%s requested_mode=%u actual_mode=%u fast_numeric=%s\n",scenario.c_str(),mode,net.EffectiveModelMode(),std::getenv("DLSS5_FAST_NUMERIC"));net.SetNoise({});auto&api=net.Runtime();auto stream=net.Stream();void*in{},*out{};api.Check(api.hipMalloc(&in,input.size()),"allocate input");api.Check(api.hipMalloc(&out,size_t(w)*h*12),"allocate output");api.Check(api.hipMemcpy(in,input.data(),input.size(),1),"upload input once");
 auto download=[&](const char*name){std::vector<float>v(size_t(w)*h*3);api.Check(api.hipMemcpy(v.data(),out,v.size()*4,2),"read output");for(float x:v)if(!std::isfinite(x))throw std::runtime_error("nonfinite output");std::ofstream f(std::string(argv[5])+"/"+name,std::ios::binary);if(!f.write(reinterpret_cast<char*>(v.data()),v.size()*4))throw std::runtime_error("output write");return v;};
 std::map<unsigned,std::vector<float>>first;for(U i=0;i<measured;i++){if(scenario=="hot-mp"){if(i==1)net.SetModelMode(2);if(i==2)net.SetModelMode(1);}net.GapTraceBegin(i);net.Enqueue(in,nullptr,out,0);net.Synchronize();net.GapTraceEnd();auto v=download((std::string("frame-")+std::to_string(i)+".rgb32f").c_str());auto mode_now=net.EffectiveModelMode();auto it=first.find(mode_now);if(it==first.end())first.emplace(mode_now,v);else if(v.size()!=it->second.size()||memcmp(v.data(),it->second.data(),v.size()*4))throw std::runtime_error("repeated frozen trace output differs");}
 printf("GAP_TRACE_DONE case=%s frames=%u finite=1 repeat_bitdiff=0 timing_not_collected=1\n",scenario.c_str(),measured);api.hipFree(in);api.hipFree(out);return 0;
}catch(const std::exception&e){fprintf(stderr,"SYNC_NETWORK_FAIL %s\n",e.what());return 1;}}
